from openai import OpenAI

client = OpenAI(
    api_key="YOUR_KIMI_API_KEY",
    base_url="https://api.moonshot.cn/v1",
)

response = client.chat.completions.create(
    model="moonshot-v1-8k",
    messages=[
        {
            "role": "system",
            "content": "Classify the sentiment of product reviews. Return JSON with fields: sentiment (positive|negative|neutral), confidence (float 0-1), key_phrases (array of strings)."
        },
        {
            "role": "user",
            "content": "The battery life is incredible but the screen could be brighter. Overall I'm happy with the purchase."
        }
    ],
    response_format={"type": "json_object"}
)

import json
result = json.loads(response.choices[0].message.content)
print(result["sentiment"], result["confidence"])
